import io, json, glob, os, re
from datetime import datetime, timezone

issues = []

# Check 1: done items with empty verification or uncovered criteria
# Check 3: orphans, cycles, parents done over non-terminal children
# Check 4: stale heartbeats, generation >= 3
# Check 6: glossary drift

VALID_STATUSES = {'proposed', 'ready', 'in_progress', 'blocked', 'needs_split', 'in_review', 'changes_requested', 'done', 'cancelled'}
VALID_TYPES = {'Objective', 'Phase', 'Capability', 'Task', 'Probe', 'Coordinator', 'Interface', 'Gate'}

items = {}
for p in glob.glob('.program/ledger/items/*.md'):
    item_id = os.path.basename(p).replace('.md', '')
    txt = io.open(p, encoding='utf-8').read()

    # Extract front matter
    fm_match = re.search(r'^---\n(.*?)\n---', txt, re.DOTALL)
    if not fm_match:
        issues.append(f"CHECK-META: {item_id} has no front matter")
        continue

    fm_text = fm_match.group(1)
    fm = {}
    for line in fm_text.split('\n'):
        if ':' in line:
            k, v = line.split(':', 1)
            fm[k.strip()] = v.strip()

    items[item_id] = {
        'status': fm.get('status', 'MISSING'),
        'type': fm.get('type', 'MISSING'),
        'depends_on': fm.get('depends_on', '[]'),
        'generation': int(fm.get('generation', '1')),
        'last_heartbeat': fm.get('last_heartbeat'),
        'text': txt,
        'fm': fm
    }

# Check 6: glossary drift
for iid, item in items.items():
    if item['status'] not in VALID_STATUSES:
        issues.append(f"CHECK-6: {iid} has invalid status '{item['status']}'")
    if item['type'] not in VALID_TYPES:
        issues.append(f"CHECK-6: {iid} has invalid type '{item['type']}'")

# Check 4: generation >= 3 (known: ROOT gen15, ROOT.1.2 gen3 done)
for iid, item in items.items():
    if item['generation'] >= 3:
        if iid not in ('ROOT', 'ROOT.1.2'):
            issues.append(f"CHECK-4: {iid} gen{item['generation']} (NEW)")

# Check 1: done items with empty verification
for iid, item in items.items():
    if item['status'] == 'done':
        # Look for verification section
        if '## Verification' in item['text']:
            ver_section = item['text'].split('## Verification')[1]
            if ver_section.split('##')[0].strip() == '':
                issues.append(f"CHECK-1: {iid} done with empty verification section")

# Check 3: parent done over non-terminal children
def get_children(parent_id):
    return [iid for iid in items if iid.startswith(parent_id + '.') and iid.count('.') == parent_id.count('.') + 1]

for iid, item in items.items():
    if item['status'] == 'done':
        children = get_children(iid)
        for child_id in children:
            child = items.get(child_id)
            if child and child['status'] not in ('done', 'cancelled'):
                issues.append(f"CHECK-3: {iid} done while child {child_id} is {child['status']}")

print(f"Issues found: {len(issues)}")
for issue in sorted(issues):
    print(issue)
